import json
from pathlib import Path

base = Path(__file__).parent / 'chunks'
translations = {
 't000001': 'Lecțiile lui Marx despre capitalism',
 't000002': 'Lecțiile lui Marx despre capitalism',
 't000003': 'Introducere',
 't000004': 'Într-o lume dominată de discursul economic, puține texte ne-au modelat înțelegerea societății și a dinamicii de clasă la fel de profund precum anumite lucrări fundamentale de teorie economică. Aceste texte monumentale cuprind nu doar critici ale capitalismului, ci și explorări vii ale condiției umane, ale relațiilor sociale și ale luptei neîncetate pentru echitate. În această călătorie intelectuală vom desface complexitatea unui sistem economic care continuă să influențeze felul în care trăim, muncim și interacționăm. De ce ar trebui să conteze astăzi aceste perspective? Într-o epocă marcată de inegalitate crescândă, consum excesiv și puterea tot mai mare a corporațiilor, temele luptei de clasă, exploatării muncii și caracterului ciclic al crizelor economice ne îndeamnă să privim critic lumea din jur. Prin această explorare, cititorii vor putea pune sub semnul întrebării starea de fapt și imagina un viitor care acordă prioritate demnității umane în locul marjelor de profit. În centrul acestei critici se află conceptul de clasă — o idee care depășește simpla clasificare economică.',
 't000005': 'Împărțirea dintre clasa capitaliștilor și clasa muncitoare nu este doar o relicvă a trecutului; este un conflict dinamic, continuu, care modelează economiile moderne. Pe măsură ce vom aprofunda subiectul, straturile acestei lupte vor arăta cum raporturile de putere influențează structurile sociale și experiențele personale. Să ne gândim la economia muncii ocazionale, în care oamenii jonglează cu mai multe slujbe, fără beneficii ori siguranță. Această manifestare modernă a exploatării muncii evocă luptele istorice ale lucrătorilor pentru salarii și drepturi echitabile. Înțelegerea acestor paralele istorice ne poate ajuta să contestăm nedreptățile actuale și să susținem schimbări semnificative. Explorând mecanismele pieței, vom întâlni „mâna invizibilă” — un concept adesea elogiat în discuțiile despre libera întreprindere. Dar ce se ascunde sub această forță aparent binevoitoare? Analiza va arăta cum mâna invizibilă, departe de a fi un ghid imparțial, perpetuează adesea inegalitatea și exploatarea. Examinând mecanismele capitalismului, vom descoperi structurile de putere ascunse care stabilesc cine prosperă și cine suferă în acest peisaj economic.',
 't000006': 'Într-o lume preocupată de sustenabilitate și consum etic, înțelegerea naturii reale a mâinii invizibile este esențială. Cum poate fi împăcată urmărirea profitului cu nevoia urgentă de responsabilitate socială? Această întrebare ne va face să reflectăm la rolul corporațiilor în modelarea valorilor noastre și la potențialul de schimbare din interiorul sistemului. Unul dintre cele mai interesante aspecte ale capitalismului este caracterul său ciclic. Crizele economice, adesea respinse ca efecte secundare nefericite ale unei piețe funcționale, devin momente decisive de reflecție și transformare. De la Marea Criză Economică până la crizele financiare ulterioare, aceste tulburări obligă societățile să înfrunte defectele sistemelor lor economice. Lecțiile crizelor trecute ne vor ajuta nu doar să înțelegem capitalismul, ci și să acționăm din timp pentru un viitor mai echitabil. Capitalismul nu se oprește la granițele naționale; este un sistem global care depășește limitele geografice. Extinderea lui a remodelat economii, culturi și societăți din întreaga lume.',
 't000007': 'Globalizarea a facilitat circulația bunurilor, capitalului și forței de muncă, dar a ridicat și probleme etice privind drepturile lucrătorilor, degradarea mediului și uniformizarea culturală. Exploatarea lucrătorilor din țările în curs de dezvoltare arată disparitățile create de capitalismul global și provoacă dezbateri urgente despre comerț echitabil, responsabilitatea corporațiilor și consumul etic. În pofida puterii răspândite a capitalului, contradicțiile capitalismului conțin și germenii schimbării revoluționare. Pe măsură ce sistemul capitalist avansează, devine tot mai instabil, iar crizele îi expun eșecurile. Recesiunile, inegalitatea și exploatarea îi pot mobiliza pe lucrători să se unească și să ceară schimbări. Posibilitatea revoluției se întemeiază pe conștiința colectivă — înțelegerea intereselor și luptelor comune ale clasei muncitoare. Când indivizii își recunosc puterea colectivă, pot contesta starea de fapt și pot imagina alternative la capitalism. În mijlocul complexității și provocărilor acestui sistem apare un fir de speranță: posibilitatea solidarității și acțiunii colective.',
 't000008': 'Istoria a arătat că, atunci când oamenii se unesc în luptele lor, pot contesta puterea bine înrădăcinată a clasei conducătoare. Mișcările de bază care apără drepturile lucrătorilor — precum lupta pentru un salariu din care să se poată trăi și pentru condiții de muncă mai bune — continuă să câștige teren. Aceste eforturi reflectă conștientizarea tot mai mare a luptei de clasă și dorința de schimbare sistemică. Ascensiunea mișcărilor sociale, alimentată de comunicarea digitală și rețelele sociale, le permite oamenilor să se conecteze, să se organizeze și să-și facă vocile auzite. În peisajul complex al capitalismului, chemarea la solidaritate răsună mai puternic ca oricând. Acțiunea colectivă, fie prin sindicate, organizații comunitare sau mișcări politice, poate amplifica vocile celor marginalizați și îi poate trage la răspundere pe cei puternici. Lupta pentru dreptate economică este profund legată de luptele mai largi pentru drepturi sociale și politice, pe măsură ce comunitățile marginalizate cer schimbări sistemice în toate aspectele societății. Această călătorie îi invită pe cititori să privească textul nu doar ca pe un artefact istoric, ci ca pe o critică vie a capitalismului, relevantă pentru realitățile actuale.',
 't000009': 'Aprofundând aceste perspective, putem înțelege mai bine forțele care ne modelează viața și posibilitățile unui viitor mai echitabil.',
 't000010': 'Cu curiozitatea trezită și mintea deschisă, pornim într-o explorare captivantă a capitalismului, menită să conteste perspectivele, să stimuleze gândirea critică și să trezească spiritul revoluționar din noi. Pe măsură ce pătrundem în complexitatea acestor dinamici economice, să păstrăm vii întrebările: Ce înseamnă să fii lucrător într-o societate capitalistă? Cum putem naviga complexitatea piețelor globalizate? Și, mai ales, cum poate acțiunea colectivă deschide drumul către o lume mai dreaptă? Urmează o călătorie care va lumina complexitatea sistemelor economice, va inspira discuții despre dreptate și echitate și va conduce, în cele din urmă, la o înțelegere mai profundă a interdependenței vieților noastre în țesătura capitalismului modern. Această explorare să dezvăluie nu doar mecanismele unui sistem economic, ci și puterea solidarității și posibilitatea schimbării transformatoare.',
 't000011': 'Capitolul I — Marfa și valoarea',
 't000012': 'În țesătura complexă a capitalismului, marfa apare ca un fir fundamental. La prima vedere, marfa pare să fie doar un produs — ceva tangibil ce poate fi cumpărat, vândut și consumat. Totuși, după cum explorează amănunțit Karl Marx în *Das Kapital*, marfa înseamnă mai mult decât forma sa fizică: ea cuprinde relații complexe între muncă, valoare și societate. Înțelegerea naturii mărfurilor este esențială pentru înțelegerea dinamicii economiilor capitaliste, deoarece dezvăluie mecanismele care determină producția și consumul. Marx ne prezintă natura dublă a mărfurilor prin două concepte-cheie: **valoarea de întrebuințare** și **valoarea de schimb**. Valoarea de întrebuințare înseamnă utilitatea unei mărfi, capacitatea ei de a satisface o nevoie sau dorință umană. Ea este calitativă și subiectivă: ce este util pentru o persoană poate să nu fie pentru alta. De pildă, o pâine are o mare valoare de întrebuințare pentru cineva flămând, dar poate conta prea puțin pentru cineva cu intoleranță la gluten. În schimb, valoarea de schimb este un concept mai abstract.',
 't000013': 'Ea desemnează valoarea unei mărfi în raport cu alte mărfuri din piață. Valoarea de schimb se stabilește cantitativ prin cantitatea dintr-o marfă ce poate fi schimbată pe alta. În acest context, banii servesc drept echivalent universal, simplificând schimbul. Relația dintre valoarea de întrebuințare și valoarea de schimb devine crucială pe măsură ce capitalismul evoluează; adesea, cea din urmă are prioritate, iar piața ajunge dominată de motivația profitului în locul nevoilor umane reale. Această tensiune este deosebit de relevantă astăzi. Într-o epocă a consumului excesiv, transformarea vieții cotidiene în marfă ridică întrebări importante. Consumă oamenii produse care le îmbunătățesc cu adevărat viața sau doar urmează tendințe impuse de marketing și presiunea socială? Goana neîncetată după profit poate duce la supraproducție și risipă, când mărfurile sunt scoase pe bandă rulantă nu pentru a satisface nevoi reale, ci pentru a stimula consumul. Astfel se creează un ciclu care pune valoarea de schimb înaintea valorii de întrebuințare și îi îndepărtează pe consumatori de adevăratul scop al mărfurilor cu care interacționează.',
 't000064': 'Prin solidaritate, apărarea dreptății și imaginarea unor alternative, putem deschide drumul către o lume în care sistemele economice servesc omenirea în loc să o exploateze. Să pornim împreună spre un viitor mai echitabil și mai sustenabil, întemeiat pe demnitate, dreptate și putere colectivă.',
 't000065': 'Pentru a înțelege pe deplin dinamica complexă a capitalismului și criticile prezentate în această explorare, lectura lucrării Das Kapital a lui Karl Marx poate oferi perspective neprețuite. Opera sa oferă o înțelegere profundă a sistemelor economice, luptelor de clasă și forțelor care modelează societatea. Celor dornici să aprofundeze aceste idei, lectura lui Das Kapital le va lumina contextul istoric și cadrele teoretice care continuă să fie relevante și astăzi.',
 't000066': 'Bibliografie',
 't000067': 'Marx, K. (1867). Das Kapital: Kritik der politischen Ökonomie [Capital: Critique of Political Economy]. Verlag von Otto Meissner.',
}

for number in (1, 2, 13):
    path = base / f'{number:04d}.json'
    data = json.loads(path.read_text())
    for segment in data['segments']:
        segment['translation'] = translations[segment['id']]
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
